/**
 * promptMarkdownUtils.mjs — build-time prompt bundler.
 *
 * Reads all .md files from src/lib/prompts/system/ in alphabetical order,
 * concatenates them, and writes a TypeScript module that exports the
 * assembled base prompt as a string. This runs:
 *   - Once during `vite build` (production)
 *   - On every dev launch via smart-dev.mjs
 *   - Manually: `node build/promptMarkdownUtils.mjs`
 *
 * The generated file (_system-prompt-bundle.ts) is gitignored — it's a
 * build artifact, not source. Editing prompt content means editing the
 * .md files, then rebuilding.
 *
 * User overrides: if ~/.tide/prompts/ (or ~/.tide-dev/prompts/) contains
 * .md files, they're appended AFTER the built-in prompts — allowing users
 * to add custom instructions without modifying the app source.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

const PROMPTS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'system');
const AGENTS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'agents');
const TOOLS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'tools');
const OUTPUT_FILE = path.join(ROOT, 'src', 'lib', 'prompts', '_system-prompt-bundle.ts');
const RUST_OUTPUT_FILE = path.join(ROOT, 'src-tauri', 'system-prompt.md');
const AGENTS_OUTPUT = path.join(ROOT, 'src', 'lib', 'prompts', '_agent-prompts-bundle.ts');
const TOOLS_OUTPUT = path.join(ROOT, 'src', 'lib', 'prompts', '_tool-descriptions-bundle.ts');
const SKILLS_DIR = path.join(ROOT, 'src', 'lib', 'prompts', 'skills');
const SKILLS_OUTPUT = path.join(ROOT, 'src', 'lib', 'prompts', '_skills-bundle.ts');

function readPromptFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .sort() // alphabetical = numeric prefix ordering (01-, 02-, etc.)
    .map((f) => {
      const raw = fs.readFileSync(path.join(dir, f), 'utf-8');
      // Strip HTML comment frontmatter (<!-- ... -->) from the top.
      const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();
      return { name: f, content };
    });
}

/** Strip YAML frontmatter (--- ... ---) and the attribution HTML comment. */
function stripFrontmatter(raw) {
  return raw
    .replace(/^---\s*\n[\s\S]*?\n---\s*\n?/, '')
    .replace(/^<!--[\s\S]*?-->\s*/, '')
    .trim();
}

function buildBundle() {
  const fragments = readPromptFiles(PROMPTS_DIR);

  if (fragments.length === 0) {
    console.warn('[prompts] No .md files found in', PROMPTS_DIR);
    return;
  }

  // Concatenate all fragments with double newlines between them.
  const assembled = fragments
    .map((f) => f.content)
    .join('\n\n');

  // Generate the TS module.
  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/system/*.md (sorted alphabetically).
 * Rebuild: node build/promptMarkdownUtils.mjs
 */
export const BASE_SYSTEM_PROMPT = ${JSON.stringify(assembled)};
`;

  fs.writeFileSync(OUTPUT_FILE, ts, 'utf-8');
  console.log(`[prompts] bundled ${fragments.length} files → ${path.relative(ROOT, OUTPUT_FILE)}`);
  for (const f of fragments) {
    console.log(`  ${f.name} (${f.content.length} chars)`);
  }

  // Rust twin: the SAME fragment order/content as the TS bundle, as one
  // concatenated markdown file the Tauri orchestrator include_str!s. This one
  // IS committed — cargo has no "generate at build time from ../../src" step,
  // so the checked-in file is the artifact (rebuild via this script after
  // editing the .md fragments).
  fs.writeFileSync(
    RUST_OUTPUT_FILE,
    '<!--\nAUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.\nSource: src/lib/prompts/system/*.md (sorted alphabetically), identical to\nthe renderer bundle (src/lib/prompts/_system-prompt-bundle.ts).\nRebuild: node build/promptMarkdownUtils.mjs\n-->\n\n' + assembled + '\n',
    'utf-8',
  );
  console.log(`[prompts] wrote rust system prompt → ${path.relative(ROOT, RUST_OUTPUT_FILE)}`);
}

function buildAgentBundle() {
  const agentFiles = fs.existsSync(AGENTS_DIR)
    ? fs.readdirSync(AGENTS_DIR).filter((f) => f.endsWith('.md')).sort()
    : [];

  if (agentFiles.length === 0) {
    console.warn('[prompts] No agent .md files found in', AGENTS_DIR);
    return;
  }

  // Parse frontmatter + content from each agent MD file.
  const agents = [];
  for (const f of agentFiles) {
    const raw = fs.readFileSync(path.join(AGENTS_DIR, f), 'utf-8');
    // Extract frontmatter fields.
    const nameMatch = raw.match(/name:\s*"([^"]+)"/);
    const descMatch = raw.match(/description:\s*"([^"]+)"/);
    const whenMatch = raw.match(/whenToUse:\s*"([^"]+)"/);
    const allowedToolsMatch = raw.match(/allowedTools:\s*"([^"]+)"/);
    const maxStepsMatch = raw.match(/maxSteps:\s*(\d+)/);
    const thinkingLevelMatch = raw.match(/thinkingLevel:\s*"([^"]+)"/);
    const canDispatchMatch = raw.match(/canDispatch:\s*"([^"]+)"/);
    const hiddenMatch = raw.match(/hidden:\s*(true|false)/);
    // Strip frontmatter for the prompt content.
    const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();

    agents.push({
      name: nameMatch ? nameMatch[1] : f.replace('.md', ''),
      description: descMatch ? descMatch[1] : '',
      whenToUse: whenMatch ? whenMatch[1] : '',
      systemPrompt: content,
      allowedTools: allowedToolsMatch ? allowedToolsMatch[1].split(',').map(s => s.trim()) : undefined,
      maxSteps: maxStepsMatch ? parseInt(maxStepsMatch[1]) : undefined,
      thinkingLevel: thinkingLevelMatch ? thinkingLevelMatch[1] : undefined,
      canDispatch: canDispatchMatch
        ? (canDispatchMatch[1].trim() === '*'
            ? 'all'
            : canDispatchMatch[1].split(',').map((s) => s.trim()).filter(Boolean))
        : undefined,
      hidden: hiddenMatch ? hiddenMatch[1] === 'true' : undefined,
    });
  }

  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/agents/*.md
 * Rebuild: node build/promptMarkdownUtils.mjs
 *
 * Each agent is dynamically loaded from its .md file — adding a new .md file
 * to src/lib/prompts/agents/ automatically creates a new builtin agent.
 * No code changes needed — just rebuild.
 */
export interface BundledAgent {
  name: string;
  description: string;
  whenToUse: string;
  systemPrompt: string;
  allowedTools?: string[];
  maxSteps?: number;
  thinkingLevel?: string;
  canDispatch?: string[] | 'all';
  hidden?: boolean;
}

export const BUNDLED_AGENTS: BundledAgent[] = ${JSON.stringify(agents, null, 2)};

/** Pre-assembled agent list for the system prompt (dispatch triggers + descriptions). */
export const AGENT_LIST_MD = ${JSON.stringify(
  '# Sub-agents — dispatch them\n' +
  'Sub-agents are multi-step specialists with their own tool loop — they investigate in their own context window and return a report, keeping yours small. Dispatch is cheap: issue it, keep working, read the report when it lands.\n\n' +
  '**Dispatch when:**\n' +
  '- The work is a multi-step investigation across many files (broad question, unknown locations)\n' +
  '- A specialty matches the job — \`code-reviewer\` for reviewing a diff, \`simplifier\` for a cleanup pass, \`explore\` for locating code, \`general-purpose\` when nothing narrower fits\n' +
  '- Several independent subtasks could run at once — dispatch them together in one response; they run in parallel\n' +
  '- The research would flood your context but only the conclusions matter\n\n' +
  '**Skip dispatch when:** you already know the answer, it is one targeted read/grep, or the user asked you to do it directly.\n\n' +
  '**Available agents:**\n' +
  agents.map((a) => '- **' + a.name + '** — ' + a.whenToUse).join('\n') + '\n\n' +
  '**How to dispatch well:**\n' +
  '- Pass a self-contained \`task\` — the agent sees only that string, not prior conversation\n' +
  '- Prefer the specialist over general-purpose when one fits; dispatch several specialists in parallel rather than one generic agent sequentially\n' +
  '- Use the report as input to your next step; if incomplete, resume the same agent with \`resumeFrom\` and sharper instructions\n' +
  '- You make the edits yourself from the reports — except \`simplifier\`, which applies its own fixes'
)};
`;

  fs.writeFileSync(AGENTS_OUTPUT, ts, 'utf-8');
  console.log(`[prompts] bundled ${agents.length} agent files → ${path.relative(ROOT, AGENTS_OUTPUT)}`);
  for (const a of agents) {
    console.log(`  ${a.name}.md (${a.systemPrompt.length} chars) — ${a.description.slice(0, 50)}`);
  }
}

function buildToolBundle() {
  const toolFiles = fs.existsSync(TOOLS_DIR)
    ? fs.readdirSync(TOOLS_DIR).filter((f) => f.endsWith('.md')).sort()
    : [];

  if (toolFiles.length === 0) {
    console.warn('[prompts] No tool .md files found in', TOOLS_DIR);
    return;
  }

  const tools = [];
  for (const f of toolFiles) {
    const raw = fs.readFileSync(path.join(TOOLS_DIR, f), 'utf-8');
    const nameMatch = raw.match(/name:\s*"([^"]+)"/);
    const descMatch = raw.match(/description:\s*"([^"]+)"/);
    const catMatch = raw.match(/category:\s*"([^"]+)"/);
    const content = raw.replace(/^<!--[\s\S]*?-->\s*/, '').trim();

    tools.push({
      name: nameMatch ? nameMatch[1] : f.replace('.md', ''),
      description: descMatch ? descMatch[1] : '',
      category: catMatch ? catMatch[1] : 'Other',
      promptText: content,
    });
  }

  // Group by category for the system prompt section.
  const categories = {};
  for (const t of tools) {
    if (!categories[t.category]) categories[t.category] = [];
    categories[t.category].push(t.promptText);
  }

  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/tools/*.md
 * Rebuild: node build/promptMarkdownUtils.mjs
 *
 * Each tool description is dynamically loaded from its .md file — adding a
 * new .md file to src/lib/prompts/tools/ automatically includes it in the
 * system prompt's tool list.
 */
export interface BundledTool {
  name: string;
  description: string;
  category: string;
  promptText: string;
}

export const BUNDLED_TOOLS: BundledTool[] = ${JSON.stringify(tools, null, 2)};

/** Pre-assembled tool list grouped by category, ready for the system prompt. */
export const TOOL_LIST_MD = ${JSON.stringify(
  Object.entries(categories)
    .map(([cat, lines]) => `**${cat}:**\n` + lines.join('\n'))
    .join('\n\n')
)};
`;

  fs.writeFileSync(TOOLS_OUTPUT, ts, 'utf-8');
  console.log(`[prompts] bundled ${tools.length} tool files → ${path.relative(ROOT, TOOLS_OUTPUT)}`);
  for (const t of tools) {
    console.log(`  ${t.name}.md — ${t.category} — ${t.description.slice(0, 50)}`);
  }
}

function buildSkillsBundle() {
  if (!fs.existsSync(SKILLS_DIR)) {
    console.warn('[prompts] No skills dir at', SKILLS_DIR);
    return;
  }

  // Bootstrap: skills/_bootstrap.md — injected into every system prompt.
  const bootstrapFile = path.join(SKILLS_DIR, '_bootstrap.md');
  let bootstrap = '';
  if (fs.existsSync(bootstrapFile)) {
    bootstrap = stripFrontmatter(fs.readFileSync(bootstrapFile, 'utf-8'));
  }

  const skills = [];
  const dirs = fs.readdirSync(SKILLS_DIR, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith('.'))
    .sort((a, b) => a.name.localeCompare(b.name));

  for (const d of dirs) {
    const skillMd = path.join(SKILLS_DIR, d.name, 'SKILL.md');
    if (!fs.existsSync(skillMd)) continue;
    const raw = fs.readFileSync(skillMd, 'utf-8');
    const nameMatch = raw.match(/name:\s*"([^"]+)"/);
    const descMatch = raw.match(/description:\s*"([^"]+)"/);
    let body = stripFrontmatter(raw);

    // Inline nested reference .md files (techniques, anti-patterns) —
    // appended under "# Reference: <file>" so the skill is self-contained.
    const nested = fs.readdirSync(path.join(SKILLS_DIR, d.name))
      .filter((f) => f.endsWith('.md') && f !== 'SKILL.md')
      .sort();
    for (const n of nested) {
      const nestedRaw = fs.readFileSync(path.join(SKILLS_DIR, d.name, n), 'utf-8');
      body += '\n\n---\n\n# Reference: ' + n.replace(/\.md$/, '') + '\n\n' + stripFrontmatter(nestedRaw);
    }

    skills.push({
      name: nameMatch ? nameMatch[1] : d.name,
      description: descMatch ? descMatch[1] : '',
      body,
    });
  }

  const ts = `/**
 * AUTO-GENERATED by build/promptMarkdownUtils.mjs — DO NOT EDIT.
 * Source: src/lib/prompts/skills/<name>/SKILL.md (+ nested reference .md, inlined)
 * Rebuild: node build/promptMarkdownUtils.mjs
 *
 * Adapted from obra/superpowers (MIT) — see THIRD_PARTY_NOTICES.md.
 */
export interface BundledSkill {
  name: string;
  description: string;
  body: string;
}

export const BUNDLED_SKILLS: BundledSkill[] = ${JSON.stringify(skills, null, 2)};

/** Bootstrap (adapted using-superpowers) — appended to every system prompt. */
export const SKILLS_BOOTSTRAP = ${JSON.stringify(bootstrap)};
`;
  fs.writeFileSync(SKILLS_OUTPUT, ts, 'utf-8');
  console.log(`[prompts] bundled ${skills.length} skills → ${path.relative(ROOT, SKILLS_OUTPUT)} (bootstrap ${bootstrap.length} chars)`);
  for (const s of skills) console.log(`  ${s.name} (${s.body.length} chars)`);
}

buildBundle();
buildAgentBundle();
buildToolBundle();
buildSkillsBundle();
